"use client";

import { useEffect, useMemo, useState } from "react";
import "./form-additions.css";
import {useAuth} from "./auth-context";
import {appFetch as fetch,appPath} from "../lib/app-path";

type OperatorAssignment={name:string;role:string;startTime:string;endTime:string};
type Event = { id?: number; title: string; program: string; requestingArea?:string; locationType?: string; usageCategory?:string; locationDetail?:string; date?: string; startTime?: string; endTime?: string; start?: string; end?: string; color: string; kind?: string; weekdays?:string; resource?:string; requester?: string; requesterEmail?:string; requesterPhone?:string; crew?:number; crewDetail?:string; assignedOperators?:OperatorAssignment[]; editingRequests?:string[];assignedEditingStaff?:{role:string;name:string}[]; equipment?:string; requirements?:string; notes?:string; status?:string; sameDayCancellation?:boolean; actualStartTime?:string; actualEndTime?:string;delayMinutes?:number;delayReason?:string;soundSetPeople?:number;soundMicrophones?:number;soundInstrumentLines?:number;soundOwnSystem?:boolean;approvalBy?:string;denialReason?:string };
type User = { id:number; email:string; name:string; program:string; role:string; active:boolean };
type Log = {id:number;reservationId:number;action:string;actorEmail:string;actorName:string;changes:string;createdAt:string};
type Program={id:number;name:string;color:string;logoData:string;active:boolean};
type Block={id:number;program:string;title:string;startTime:string;endTime:string;kind:string;color:string;weekdays:string;resource:string;active:boolean};
type InventoryItem={id:number;name:string;category:string;stock:number|null;unit:string;active:boolean};
type StaffMember={id:number;name:string;role:string;studios:string;active:boolean};
type EditingMember={id:number;name:string;role:string;active:boolean};
const COLORS = ["#4976BA", "#E26954", "#56A68A", "#8D6CC4", "#E5A23B", "#D1709A"];
const MONTHS = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
const DAYS = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const AREAS=["PRODUCCIÓN","REDACCIÓN","COMERCIAL","MARKETING","TI","GERENCIA","TALENTO HUMANO"];
const CREW_ROLES=["REALIZADOR","SONIDISTA","OPERADOR DE VTR","CAMARÓGRAFO","ASISTENTE DE SONIDO","TÉCNICO","ILUMINADOR","TITULADOR"];
const OPERATIONAL_CREW_ROLES=CREW_ROLES.filter(role=>role!=="TÉCNICO"),TECHNICAL_CREW_ROLES=CREW_ROLES.filter(role=>role==="TÉCNICO");
const EDITING_ROLES=["EDITOR","CAMAROGRAFO","FILMAKER","CLIPEADOR"];
const EQUIPMENT_NEEDS=["CÁMARAS","LUCES","MICRÓFONOS","AUDIO","INTERCOMUNICACIÓN","CABLEADO / ENERGÍA","MONITOREO / VTR","OTRO APOYO"];
const CHANGE_REASONS=["Canceló el invitado","Falla de coordinación","No llegó el invitado","Falla técnica u operativa","Otro"];

function iso(date: Date) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`; }
function addDays(date: Date, n: number) { const d = new Date(date); d.setDate(d.getDate()+n); return d; }
function monday(date: Date) { const d = new Date(date); d.setDate(d.getDate() - ((d.getDay()+6)%7)); return d; }
function formatDate(date: Date) { return `${date.getDate()} de ${MONTHS[date.getMonth()]}`; }
function timeMinutes(value:string){const [hour,minute]=value.split(":").map(Number);return Number.isFinite(hour)&&Number.isFinite(minute)?hour*60+minute:0}
function normalized(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim().toUpperCase()}
function isSoundsProgram(value:string){return normalized(value)==="SONIDOS DE LA REDACCION"}
function needsManualStaff(date:string,location:string){return location==="exteriores"||(location==="estudio"&&new Date(`${date}T12:00:00`).getDay()===6)}

export default function Home() {
  const {user}=useAuth();
  const [view, setView] = useState<"día"|"semana"|"mes">("semana");
  const [cursor, setCursor] = useState(new Date());
  const [reservations, setReservations] = useState<Event[]>([]);
  const [fixed, setFixed] = useState<Event[]>([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(false);
  const [toast, setToast] = useState("");
  const [error, setError] = useState("");
  const [sending, setSending] = useState(false);
  const [admin, setAdmin] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [resource, setResource] = useState<"estudio"|"exteriores"|"radio">("estudio");
  const [editing, setEditing] = useState<Event|null>(null);
  const [logs, setLogs] = useState<Log[]>([]);
  const [logsOpen, setLogsOpen] = useState(false);
  const [metricsOpen,setMetricsOpen]=useState(false);
  const [metrics,setMetrics]=useState<Record<string,number|Record<string,number>>>({});
  const [metricMonth,setMetricMonth]=useState(new Date().toISOString().slice(0,7));
  const [programs,setPrograms]=useState<Program[]>([]);
  const [blocks,setBlocks]=useState<Block[]>([]);
  const [operationsOpen,setOperationsOpen]=useState(false);
  const [formLocation,setFormLocation]=useState<"estudio"|"exteriores"|"radio">("estudio");
  const [formArea,setFormArea]=useState("PRODUCCIÓN");
  const [formDate,setFormDate]=useState(iso(new Date()));
  const [formStart,setFormStart]=useState("");
  const [formEnd,setFormEnd]=useState("");
  const [formProgram,setFormProgram]=useState("");
  const [soundOwnSystem,setSoundOwnSystem]=useState(false);
  useEffect(()=>{if(modal)setFormArea(editing?.requestingArea||"PRODUCCIÓN")},[modal,editing]);
  useEffect(()=>{if(formArea==="TALENTO HUMANO"){setRequestedRoles([]);setCrewCount(0);setOperatorAssignments([])}},[formArea]);
  const [operatorAssignments,setOperatorAssignments]=useState<OperatorAssignment[]>([]);
  const [requestedRoles,setRequestedRoles]=useState<string[]>([]);
  const [manualNames,setManualNames]=useState<Record<string,string>>({});
  const [crewCount,setCrewCount]=useState(0);
  const [inventory,setInventory]=useState<InventoryItem[]>([]);
  const [staff,setStaff]=useState<StaffMember[]>([]);
  const [editingStaff,setEditingStaff]=useState<EditingMember[]>([]);
  const [requestedEditingRoles,setRequestedEditingRoles]=useState<string[]>([]);
  const [editingAssignments,setEditingAssignments]=useState<Record<string,string>>({});
  const [staffOpen,setStaffOpen]=useState(false);
  const [editingStaffOpen,setEditingStaffOpen]=useState(false);
  const [cancelOpen,setCancelOpen]=useState(false);
  const [cancelReason,setCancelReason]=useState("");
  const [cancelDetail,setCancelDetail]=useState("");
  const [denialOpen,setDenialOpen]=useState(false);
  const [denialReason,setDenialReason]=useState("");

  const range = useMemo(() => {
    if (view === "día") return { from: cursor, to: addDays(cursor,1) };
    if (view === "semana") { const from = monday(cursor); return { from, to: addDays(from,7) }; }
    const from = new Date(cursor.getFullYear(),cursor.getMonth(),1); return { from, to: new Date(cursor.getFullYear(),cursor.getMonth()+1,1) };
  }, [cursor, view]);

  async function load() {
    setLoading(true);
    try {
      const res = await fetch(`/api/reservations?from=${iso(addDays(range.from,-1))}&to=${iso(range.to)}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      setReservations(data.reservations);
      const ur=await fetch("/api/users"); if(ur.ok)setUsers((await ur.json()).users);
      const [pr,sr,ir,tr,er]=await Promise.all([fetch("/api/programs"),fetch("/api/schedule"),fetch("/api/inventory"),fetch("/api/staff"),fetch("/api/editing-staff")]);if(pr.ok)setPrograms((await pr.json()).programs);if(ir.ok)setInventory((await ir.json()).items);if(tr.ok)setStaff((await tr.json()).staff);if(er.ok)setEditingStaff((await er.json()).staff);if(sr.ok){const b=(await sr.json()).blocks;setBlocks(b);setFixed(b.filter((x:Block)=>x.active).map((x:Block)=>({...x,start:x.startTime,end:x.endTime})))}
    } catch { setError("No se pudo cargar la agenda. Intente nuevamente."); }
    finally { setLoading(false); }
  }
  useEffect(() => { load(); }, [range.from.getTime(), range.to.getTime()]);
  useEffect(()=>{let current=true;if(!modal||!formDate||!formStart||!formEnd||!formProgram||formStart>=formEnd||!requestedRoles.length){setOperatorAssignments([]);return}const query=new URLSearchParams({date:formDate,resource:formLocation,program:formProgram,start:formStart,end:formEnd,roles:requestedRoles.join("|")});fetch(`/api/operators?${query}`).then(r=>r.json()).then(d=>{if(!current)return;const assigned=d.assignments||[];setOperatorAssignments(assigned.length?assigned:[{role:"PENDIENTE",name:"OPERACIONES DEBE DESIGNAR EL PERSONAL",startTime:formStart,endTime:formEnd}])}).catch(()=>{if(current)setOperatorAssignments([])});return()=>{current=false}},[modal,formDate,formStart,formEnd,formProgram,formLocation,requestedRoles.join("|")]);

  const step = view === "día" ? 1 : view === "semana" ? 7 : 30;
  const title = view === "día" ? formatDate(cursor) : view === "semana" ? `${formatDate(range.from)} — ${formatDate(addDays(range.to,-1))}` : `${MONTHS[cursor.getMonth()]} ${cursor.getFullYear()}`;

  async function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError(""); setSending(true);
    const form = new FormData(e.currentTarget);
    const raw=Object.fromEntries(form.entries()),crewRoles=form.getAll("crewRoles").map(String),editingRoles=form.getAll("editingRoles").map(String),manualAssignments=crewRoles.map(role=>({role,name:String(form.get(`manual_${role}`)||""),startTime:formStart,endTime:formEnd})),equipmentNeeds=formLocation==="exteriores"?form.getAll("equipmentNeeds").map(String):[];const selectedProgram=programs.find(p=>p.name===raw.program);const payload = {...raw,title:raw.program,crew:crewRoles.length,crewDetail:crewRoles.join(", "),editingRoles,manualAssignments,equipment:equipmentNeeds.join(", "),color:selectedProgram?.color||raw.color,soundOwnSystem,...(editing?{id:editing.id}:{})};
    try {
      let res = await fetch("/api/reservations", { method:editing?"PATCH":"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload) });
      let data = await res.json();
      if(!res.ok&&["FIXED_OVERLAP_CONFIRMATION_REQUIRED","FIXED_OVERRIDE_CONFIRMATION_REQUIRED"].includes(data.code)){
        const accepted=window.confirm(`ADVERTENCIA DE SOLAPAMIENTO\n\n${data.error}\n\nLa grabación quedará visible sobre el bloque fijo en la agenda y permanecerá pendiente hasta la aprobación de Jefe de Producción. ¿Desea continuar?`);
        if(!accepted)return;
        res=await fetch("/api/reservations",{method:editing?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...payload,allowFixedOverride:true})});
        data=await res.json();
      }
      if (!res.ok) throw new Error(data.error);
      setModal(false); setEditing(null); setToast(editing ? "Solicitud actualizada y enviada nuevamente a aprobación." : data.emailStatus === "enviado" ? "Solicitud registrada, pendiente de aprobación del Productor; correo enviado." : data.emailStatus==="error" ? `Solicitud registrada y pendiente de aprobación, pero el correo no se envió: ${data.emailError||"revise la configuración SMTP."}` : "Solicitud registrada y pendiente de aprobación del Productor.");
      await load(); setTimeout(()=>setToast(""),5000);
    } catch (err) { setError(err instanceof Error ? err.message : "No se pudo reservar."); }
    finally { setSending(false); }
  }
  async function openAdmin(){setAdmin(true);setError("");const r=await fetch("/api/users");const d=await r.json();if(r.ok)setUsers(d.users);else setError(d.error)}
  async function addUser(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget).entries());const r=await fetch("/api/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)});const d=await r.json();if(!r.ok){setError(d.error);return}setUsers([...users,d.user]);e.currentTarget.reset()}
  async function toggleUser(user:User){const r=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:user.id,active:!user.active})});if(r.ok)setUsers(users.map(u=>u.id===user.id?{...u,active:!u.active}:u))}
  async function addStaff(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget).entries());const r=await fetch("/api/staff",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)}),d=await r.json();if(!r.ok){setError(d.error);return}setStaff([...staff,d.member]);e.currentTarget.reset();setToast("Personal operativo agregado al catálogo.")}
  async function toggleStaff(member:StaffMember){const r=await fetch("/api/staff",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:member.id,active:!member.active})}),d=await r.json();if(r.ok)setStaff(staff.map(s=>s.id===member.id?d.member:s));else setError(d.error)}
  async function addEditingStaff(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget).entries());const r=await fetch("/api/editing-staff",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)}),d=await r.json();if(!r.ok){setError(d.error);return}setEditingStaff([...editingStaff,d.member]);e.currentTarget.reset();setToast("Personal de edición agregado al catálogo.")}
  async function toggleEditingStaff(member:EditingMember){const r=await fetch("/api/editing-staff",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:member.id,active:!member.active})}),d=await r.json();if(r.ok)setEditingStaff(editingStaff.map(s=>s.id===member.id?d.member:s));else setError(d.error)}
  async function openLogs(){const r=await fetch("/api/logs");const d=await r.json();if(r.ok){setLogs(d.logs);setLogsOpen(true)}else setError(d.error)}
  async function openMetrics(month=metricMonth){const r=await fetch(`/api/metrics?month=${month}`);const d=await r.json();if(r.ok){setMetrics(d);setMetricsOpen(true)}else setError(d.error)}
  function actorEmail(){return user?.email||""}
  async function cancelReservation(){if(!editing?.id)return;const r=await fetch("/api/reservations",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,actorEmail:actorEmail(),reason:cancelReason,detail:cancelDetail})});const d=await r.json();if(!r.ok){setError(d.error);return}setCancelOpen(false);setModal(false);setEditing(null);setCancelReason("");setCancelDetail("");setToast(d.emailStatus==="enviado"?"Grabación cancelada y correo enviado.":"Grabación cancelada; correo pendiente de configuración.");await load()}
  async function reviewReservation(action:"approve"|"deny",reason?:string){if(!editing?.id)return;if(action==="deny"&&reason===undefined){setError("");setDenialReason("");setDenialOpen(true);return}if(action==="deny"&&(reason||"").trim().length<3){setError("Explique brevemente el motivo del rechazo.");return}const r=await fetch("/api/reservations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,action,reason:reason||""})}),d=await r.json();if(!r.ok){setError(d.error);return}setDenialOpen(false);setModal(false);setEditing(null);setToast(action==="approve"?`Reserva aprobada por ${isProductionChief?"Jefe de Producción":"el responsable de agenda"}.`:d.emailStatus==="enviado"?"Solicitud rechazada; se notificó al solicitante por correo.":"Solicitud rechazada y registrada. Revise la configuración SMTP para enviar el correo.");await load()}
  async function assignEditingStaff(){if(!editing?.id)return;const assignments=(editing.editingRequests||[]).map(role=>({role,name:editingAssignments[role]||""}));const r=await fetch("/api/reservations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,action:"assign-editing",assignments})}),d=await r.json();if(!r.ok){setError(d.error);return}setEditing(d.reservation);setEditingAssignments(Object.fromEntries((d.reservation.assignedEditingStaff||[]).map((item:{role:string;name:string})=>[item.role,item.name])));setToast("Personal de edición designado y registrado en bitácora.");await load()}
  async function completeReservation(){if(!editing?.id)return;const start=prompt("Hora real de inicio (HH:MM)",editing.startTime)||"",end=prompt("Hora real de fin (HH:MM)",editing.endTime)||"";if(!start||!end)return;const r=await fetch("/api/reservations",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,actorEmail:actorEmail(),actualStartTime:start,actualEndTime:end})});const d=await r.json();if(!r.ok){setError(d.error);return}setModal(false);setEditing(null);setToast("Grabación finalizada; horas reales registradas.");await load()}
  async function markDelay(){if(!editing?.id)return;const start=prompt("Nueva hora estimada/real de inicio (HH:MM)",editing.actualStartTime||editing.startTime)||"",reason=prompt("Motivo del retraso",editing.delayReason||"")||"";if(!start)return;const r=await fetch("/api/reservations",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,actorEmail:actorEmail(),actualStartTime:start,action:"delay",delayReason:reason})});const d=await r.json();if(!r.ok){setError(d.error);return}setModal(false);setEditing(null);setToast(`Retraso registrado: ${d.reservation.delayMinutes} minutos.`);await load()}
  async function permanentDelete(){if(!editing?.id)return;const confirmation=prompt("Esta acción borrará totalmente la solicitud y su bitácora. No afectará las métricas y no se puede deshacer.\n\nEscriba ELIMINAR para continuar:");if(confirmation!=="ELIMINAR")return;const r=await fetch("/api/reservations/purge",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id})});const d=await r.json();if(!r.ok){setError(d.error);return}setModal(false);setEditing(null);setToast("Solicitud de prueba eliminada totalmente.");await load()}
  async function addProgram(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget),file=fd.get("logo") as File;try{const image=file?.size?await logoData(file):"";const r=await fetch("/api/programs",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:fd.get("name"),color:fd.get("color"),logoData:image})});const d=await r.json();if(!r.ok)throw new Error(d.error);setPrograms([...programs,d.program]);e.currentTarget.reset();setToast("Programa agregado correctamente.")}catch(e){setError(e instanceof Error?e.message:"No se pudo agregar el programa.")}}
  async function logoData(file:File){if(!file.type.startsWith("image/"))throw new Error("Seleccione una imagen válida.");return await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("No se pudo leer la imagen."));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error("El archivo no es una imagen válida."));img.onload=()=>{const size=256,canvas=document.createElement("canvas");canvas.width=size;canvas.height=size;const ctx=canvas.getContext("2d")!;ctx.clearRect(0,0,size,size);const scale=Math.min(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);resolve(canvas.toDataURL("image/webp",.82))};img.src=String(reader.result)};reader.readAsDataURL(file)})}
  async function updateProgramLogo(program:Program,file?:File){if(!file)return;try{const data=await logoData(file);const r=await fetch("/api/programs",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...program,logoData:data})});const d=await r.json();if(!r.ok)throw new Error(d.error);setPrograms(programs.map(p=>p.id===program.id?d.program:p));setToast(`Logo de ${program.name} actualizado.`)}catch(e){setError(e instanceof Error?e.message:"No se pudo subir el logo.")}}
  async function updateProgram(program:Program,changes:Partial<Program>){const next={...program,...changes};const r=await fetch("/api/programs",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(next)});const d=await r.json();if(r.ok)setPrograms(programs.map(p=>p.id===program.id?d.program:p));else setError(d.error)}
  async function updateBlock(block:Block,changes:Partial<Block>){const next={...block,...changes};const r=await fetch("/api/schedule",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(next)});if(r.ok){setBlocks(blocks.map(b=>b.id===block.id?next:b));setFixed(blocks.map(b=>b.id===block.id?next:b).filter(b=>b.active).map(b=>({...b,start:b.startTime,end:b.endTime})))} }
  async function updateInventory(item:InventoryItem,changes:Partial<InventoryItem>){const next={...item,...changes};const r=await fetch("/api/inventory",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(next)});if(r.ok)setInventory(inventory.map(i=>i.id===item.id?next:i))}
  const fixedOverlapBlocks=formStart< formEnd?blocks.filter(block=>block.active&&block.resource===formLocation&&block.weekdays.split(",").includes(String(new Date(`${formDate}T12:00:00`).getDay()))&&timeMinutes(formStart)<timeMinutes(block.endTime)&&timeMinutes(formEnd)>timeMinutes(block.startTime)):[];
  const shownReservations=reservations.filter(r=>r.locationType===resource),isAdminUser=Boolean(user&&["administrador","jefe_operaciones"].includes(user.role)),isProducerUser=user?.role==="productor",isProductionChief=user?.role==="jefe_produccion",canPurge=user?.role==="administrador",isOperatorUser=Boolean(user?.role==="operador"),canApprove=Boolean(user&&["productor","jefe_produccion","administrador","jefe_operaciones"].includes(user.role)),canRequest=Boolean(user&&["produccion","productor","jefe_produccion","editor","administrador","jefe_operaciones"].includes(user.role)),canEditingAssign=Boolean(user&&["editor","productor","administrador","jefe_operaciones"].includes(user.role)),canAssignManualOperators=isAdminUser||isProducerUser,canOperate=isAdminUser||isOperatorUser;

  return <main>
    <header className="topbar">
      <div className="brand"><div className="mark">ED</div><div><b>Operaciones</b><span>Agenda de estudios y grabaciones</span></div></div>
      <div className="top-actions">{(isAdminUser||isProducerUser)&&<button className="admin-btn" onClick={()=>window.location.href=appPath("/admin")}>{isProducerUser?"Panel de Productor":"Dashboard"}</button>}<button className="admin-btn" onClick={openLogs}>{["administrador","jefe_produccion"].includes(user?.role||"")?"Bitácora de agenda":"Bitácora"}</button>{canEditingAssign&&<button className="admin-btn" onClick={()=>setEditingStaffOpen(true)}>Personal de edición</button>}{canRequest&&<button className="primary" onClick={()=>{setEditing(null);setCrewCount(0);setRequestedRoles([]);setRequestedEditingRoles([]);setEditingAssignments({});setManualNames({});setFormLocation(resource);setFormDate(iso(cursor));setFormStart("");setFormEnd("");setFormProgram("");setSoundOwnSystem(false);setError("");setModal(true)}}><span>＋</span> Nueva solicitud</button>}</div>
    </header>
    <section className="hero">
      <div><p className="eyebrow">EL DEBER · OPERACIONES</p><h1>GESTIÓN DE USO DE ESTUDIOS Y GRABACIONES ED</h1></div>
      <div className="status"><span className="pulse"/><div><b>Operación activa</b><small>Turnos 06:00–22:00</small></div></div>
    </section>
    <section className="workspace">
      <div className="toolbar">
        <div className="date-nav"><button aria-label="Anterior" onClick={()=>setCursor(addDays(cursor,-step))}>‹</button><button className="today" onClick={()=>setCursor(new Date())}>Hoy</button><button aria-label="Siguiente" onClick={()=>setCursor(addDays(cursor,step))}>›</button><h2>{title}</h2></div>
        <div className="segmented">{(["día","semana","mes"] as const).map(v=><button key={v} className={view===v?"active":""} onClick={()=>setView(v)}>{v[0].toUpperCase()+v.slice(1)}</button>)}</div>
      </div>
      <div className="resource-tabs"><button className={resource==="estudio"?"active":""} onClick={()=>setResource("estudio")}>Estudio II · TV</button><button className={resource==="radio"?"active":""} onClick={()=>setResource("radio")}>Estudio I · Radio</button><button className={resource==="exteriores"?"active":""} onClick={()=>setResource("exteriores")}>Exteriores</button><span>La disponibilidad se valida por separado</span></div>
      <div className="content">
          <section className="calendar-card agenda-card">
          {loading ? <div className="empty">Cargando agenda…</div> : view === "mes" ? <MonthView cursor={cursor} reservations={shownReservations}/> : <Schedule days={view==="día"?[cursor]:Array.from({length:7},(_,i)=>addDays(range.from,i))} reservations={shownReservations} fixed={fixed.filter(f=>(f as Event&{resource?:string}).resource===resource)} onEdit={(event)=>{const roles=(event.crewDetail||"").split(",").map(v=>v.trim()).filter(Boolean);setEditing(event);setCrewCount(roles.length);setRequestedRoles(roles);setRequestedEditingRoles(event.editingRequests||[]);setEditingAssignments(Object.fromEntries((event.assignedEditingStaff||[]).map(a=>[a.role,a.name])));setManualNames(Object.fromEntries((event.assignedOperators||[]).map(a=>[a.role,a.name])));setFormLocation(event.locationType as "estudio"|"exteriores"|"radio");setFormDate(event.date||iso(cursor));setFormStart(event.startTime||"");setFormEnd(event.endTime||"");setFormProgram(event.program);setSoundOwnSystem(Boolean(event.soundOwnSystem));setOperatorAssignments(event.assignedOperators||[]);setError("");setModal(true)}}/>} 
        </section>
        <aside>
        <div className="side-card"><p className="eyebrow">ESPACIOS DE HOY</p><Availability reservations={reservations} fixed={fixed}/></div>
          <div className="help"><b>¿Necesita apoyo?</b><p>Coordine requerimientos técnicos y personal con Operaciones.</p><div className="contact-links"><a href="mailto:operaciones@eldeber.com.bo?subject=Consulta%20Gestión%20de%20Grabaciones">Enviar correo</a><a href="https://wa.me/?text=Consulta%20sobre%20Gestión%20de%20Grabaciones%20ED" target="_blank" rel="noreferrer">Escribir por WhatsApp</a></div></div>
        </aside>
      </div>
    </section>
    {modal && <div className="overlay" onMouseDown={(e)=>{if(e.target===e.currentTarget)setModal(false)}}><div className="modal">
      <button className="close" onClick={()=>{setModal(false);setEditing(null)}}>×</button><p className="eyebrow">{editing?"EDITAR SOLICITUD":"NUEVA SOLICITUD"}</p><h2>{editing?editing.title:"Programar una grabación"}</h2><p className="sub">{editing?"Todos los cambios quedarán registrados.":"Los cruces de horario se validan antes de confirmar."}</p>
      <form onSubmit={submit} onChange={e=>{const input=e.target;if(input instanceof HTMLInputElement&&input.name==="crewRoles")setRequestedRoles(new FormData(e.currentTarget).getAll("crewRoles").map(String))}} key={editing?.id||"new"}>
        {formLocation==="estudio"&&<label className="usage-category-field">Categoría de uso<select key={formArea==="TALENTO HUMANO"?"talento":"general"} name="usageCategory" defaultValue={formArea==="TALENTO HUMANO"?"actividades internas":editing?.usageCategory||"grabación"} disabled={formArea==="TALENTO HUMANO"}><option value="grabación">Grabación</option><option value="actividades internas">Actividades internas</option></select></label>}
        <div className="form-grid">
          <label className="wide">Programa / contenido<select name="program" value={formProgram} onChange={e=>setFormProgram(e.target.value)} required><option value="" disabled>Seleccione programa…</option>{programs.filter(p=>p.active).map(p=><option key={p.id} value={p.name}>{p.name}</option>)}</select></label>
          {isSoundsProgram(formProgram)&&<fieldset className="wide sounds-redaction-form"><legend>Datos obligatorios · Sonidos de la Redacción</legend><label>Personas en set<input type="number" name="soundSetPeople" min="1" step="1" defaultValue={editing?.soundSetPeople||1} required/></label><label className="sounds-own"><input type="checkbox" checked={soundOwnSystem} onChange={e=>setSoundOwnSystem(e.target.checked)}/><span>Ellos traen su sonido</span></label>{soundOwnSystem?<div className="sounds-master"><b>Recepción de audio</b><span>Solo MASTER L y R</span></div>:<><label>Micrófonos<input type="number" name="soundMicrophones" min="0" step="1" defaultValue={editing?.soundMicrophones??0} required/></label><label>Líneas de instrumento<input type="number" name="soundInstrumentLines" min="0" step="1" defaultValue={editing?.soundInstrumentLines??0} required/></label></>}</fieldset>}
          <label>Área solicitante<select name="requestingArea" value={formArea} onChange={e=>setFormArea(e.target.value)}>{AREAS.map(a=><option key={a}>{a}</option>)}</select></label>
          <label>Tipo<select name="locationType" value={formLocation} onChange={e=>setFormLocation(e.target.value as "estudio"|"exteriores"|"radio")}><option value="estudio">Estudio II · TV</option><option value="radio">Estudio I · Radio</option><option value="exteriores">Exteriores</option></select></label>
          <label>Fecha<input type="date" name="date" value={formDate} onChange={e=>setFormDate(e.target.value)} required/></label>
          <label>Inicio<input type="time" name="startTime" value={formStart} onChange={e=>setFormStart(e.target.value)} min="06:00" max="22:00" step="900" required/></label>
          <label>Fin<input type="time" name="endTime" value={formEnd} onChange={e=>setFormEnd(e.target.value)} min="06:00" max="22:00" step="900" required/></label>
          {fixedOverlapBlocks.length>0&&<div className="wide radio-override-warning"><b>Advertencia: solapamiento con programación fija</b><span>La grabación coincide con: {fixedOverlapBlocks.map(block=>`${block.title} (${block.startTime}–${block.endTime})`).join(" · ")}. Puede registrarla si confirma la advertencia; quedará pendiente hasta la aprobación de Jefe de Producción.</span></div>}
          {formArea==="TALENTO HUMANO"?<div className="wide talent-human-note"><b>Solicitud sin apoyo operativo</b><span>Las actividades de Talento Humano no requieren personal operativo ni equipos.</span></div>:<>
            <fieldset className="wide check-group"><legend>Personal operativo requerido <span>({requestedRoles.filter(role=>role!=="TÉCNICO").length} funciones)</span></legend>{OPERATIONAL_CREW_ROLES.map(role=><label key={role}><input type="checkbox" name="crewRoles" value={role} checked={requestedRoles.includes(role)} onChange={e=>{setRequestedRoles(current=>e.target.checked?[...new Set([...current,role])]:current.filter(item=>item!==role));setCrewCount(c=>Math.max(0,c+(e.target.checked?1:-1)))}}/><span>{role}</span></label>)}</fieldset>
            <fieldset className="wide check-group technical-request-group"><legend>Personal técnico requerido <span>(no genera horas operativas)</span></legend>{TECHNICAL_CREW_ROLES.map(role=><label key={role}><input type="checkbox" name="crewRoles" value={role} checked={requestedRoles.includes(role)} onChange={e=>{setRequestedRoles(current=>e.target.checked?[...new Set([...current,role])]:current.filter(item=>item!==role));setCrewCount(c=>Math.max(0,c+(e.target.checked?1:-1)))}}/><span>{role}</span></label>)}</fieldset>
            {formLocation!=="exteriores"&&<fieldset className="wide check-group editing-request-group"><legend>Personal de edición solicitado <span>Lo designa el rol Editor · no genera horas operativas</span></legend>{EDITING_ROLES.map(role=><label key={role}><input type="checkbox" name="editingRoles" value={role} checked={requestedEditingRoles.includes(role)} onChange={e=>setRequestedEditingRoles(current=>e.target.checked?[...new Set([...current,role])]:current.filter(item=>item!==role))}/><span>{role}</span></label>)}</fieldset>}
            <fieldset className="wide operator-assignment"><legend>Asignación de personal</legend>{formLocation==="exteriores"?<p>Producción solicita las funciones necesarias; el Jefe de Operaciones elegirá posteriormente a las personas.</p>:operatorAssignments.length?operatorAssignments.map((a,i)=><div key={`${a.name}-${a.role}-${i}`}><b>{a.role}</b><span>{a.name}</span><small>{a.startTime}–{a.endTime}</small></div>):<p>Seleccione las funciones necesarias para calcular el personal de turno en el estudio.</p>}</fieldset>
            {formLocation==="exteriores"&&<fieldset className="wide check-group equipment-needs"><legend>Necesidades generales de equipo <span>Operaciones definirá modelos y cantidades</span></legend>{EQUIPMENT_NEEDS.map(item=><label key={item}><input type="checkbox" name="equipmentNeeds" value={item} defaultChecked={editing?.equipment?.includes(item)}/><span>{item}</span></label>)}</fieldset>}
          </>}
          {formLocation==="exteriores"&&<label className="wide">Ubicación exterior<input name="locationDetail" defaultValue={editing?.locationDetail} placeholder="Dirección o punto de encuentro" required/></label>}
          <label>Responsable<input name="requester" defaultValue={editing?.requester||user?.name} required/></label><label>Correo<input type="email" name="requesterEmail" defaultValue={editing?.requesterEmail||user?.email} required/></label><label>Teléfono<input name="requesterPhone" defaultValue={editing?.requesterPhone}/></label>
          <label className="wide">Otros requerimientos<textarea name="requirements" defaultValue={editing?.requirements}/></label><label className="wide">Observaciones<textarea name="notes" defaultValue={editing?.notes}/></label>
          {editing&&<><label>Motivo si cambia fecha u horario<select name="rescheduleReason" defaultValue=""><option value="">No aplica</option>{CHANGE_REASONS.map(r=><option key={r}>{r}</option>)}</select></label><label>Especificación del motivo<input name="rescheduleDetail" placeholder="Obligatorio cuando el motivo es Otro"/></label></>}
          {editing&&<label className="wide audit-actor">Usuario que realiza el cambio<input name="actorEmail" value={user?.email||""} readOnly/><small>{user?.name} · cambio atribuido automáticamente por la sesión</small></label>}
        </div>
        {editing&&(editing.editingRequests||[]).length>0&&<fieldset className="editing-assignment"><legend>Personal de edición</legend><p>{canEditingAssign?"Designe una persona por función solicitada. La asignación queda registrada en la bitácora.":"Solicitud enviada a Edición para la designación del personal."}</p>{editing.editingRequests!.map(role=><label key={role}><span>{role}</span>{canEditingAssign?<select value={editingAssignments[role]||""} onChange={e=>setEditingAssignments(current=>({...current,[role]:e.target.value}))}><option value="">Seleccione persona…</option>{editingStaff.filter(member=>member.active&&member.role===role).map(member=><option key={member.id} value={member.name}>{member.name}</option>)}</select>:<b>{editing.assignedEditingStaff?.find(item=>item.role===role)?.name||"Pendiente de designación"}</b>}</label>)}{canEditingAssign&&<button type="button" className="editing-save" onClick={assignEditingStaff}>Guardar designación de edición</button>}</fieldset>}
        {editing&&canAssignManualOperators&&needsManualStaff(formDate,formLocation)&&requestedRoles.length>0&&<fieldset className="manual-operator-assignment"><legend>Asignación del Jefe de Operaciones</legend><p>{formLocation==="exteriores"?"Exteriores permite combinar personal de cualquier estudio.":"Seleccione la cuadrilla rotativa para este sábado en Estudio II."}</p>{requestedRoles.map(role=><label key={role}><span>{role}</span><select name={`manual_${role}`} value={manualNames[role]||""} onChange={e=>setManualNames({...manualNames,[role]:e.target.value})}><option value="">Pendiente de asignación…</option>{staff.filter(s=>s.active&&s.role===role&&(formLocation==="exteriores"||s.studios.split(",").includes("estudio"))).map(s=><option key={s.id} value={s.name}>{s.name}</option>)}</select></label>)}</fieldset>}
        {error && <div className="form-error">{error}</div>}<div className="actions">{editing&&<>{canPurge&&<button type="button" className="admin-delete" onClick={permanentDelete}>Eliminar totalmente · Admin</button>}{(canRequest||canOperate)&&<button type="button" className="danger" onClick={()=>{setError("");setCancelOpen(true)}}>{isOperatorUser?"Reportar falla y cancelar":(isProducerUser||isProductionChief)?"Anular / cancelar grabación":"Cancelar grabación"}</button>}{canOperate&&<><button type="button" onClick={markDelay}>Marcar retraso</button><button type="button" onClick={completeReservation}>Registrar finalización</button></>}{canApprove&&!["cancelada","completada"].includes(editing.status||"")&&<><button type="button" className="deny-reservation" onClick={()=>reviewReservation("deny")}>Rechazar solicitud</button><button type="button" className="approve-reservation" onClick={()=>reviewReservation("approve")}>Aprobar solicitud</button></>}</>}<button type="button" onClick={()=>setModal(false)}>Cerrar</button>{canRequest&&<button className="primary" disabled={sending}>{sending?"Validando…":editing?"Guardar cambios":"Enviar a aprobación"}</button>}</div>
      </form>
    </div></div>}
    {admin&&<div className="overlay"><div className="modal admin-modal"><button className="close" onClick={()=>setAdmin(false)}>×</button><p className="eyebrow">ADMINISTRACIÓN</p><h2>Usuarios por programa</h2><p className="sub">El correo corporativo identifica a cada usuario del sistema.</p><form className="user-form" onSubmit={addUser}><input name="name" placeholder="Nombre completo" required/><input name="email" type="email" placeholder="correo@eldeber.com.bo" required/><input name="program" placeholder="Programa / área" required/><select name="role"><option value="produccion">Producción</option><option value="productor">Productor</option><option value="jefe_produccion">Jefe de Producción</option><option value="operador">Operador</option><option value="editor">Editor</option><option value="jefe_operaciones">Jefe de Operaciones</option><option value="administrador">Administrador</option><option value="visor">Visor de agenda</option></select><button className="primary">Agregar usuario</button></form>{error&&<div className="form-error">{error}</div>}<div className="user-list">{users.map(u=><div key={u.id}><span className={`avatar ${u.active?"":"off"}`}>{u.name.slice(0,2).toUpperCase()}</span><div><b>{u.name}</b><small>{u.email} · {u.program} · {u.role}</small></div><button onClick={()=>toggleUser(u)}>{u.active?"Desactivar":"Activar"}</button></div>)}</div></div></div>}
    {staffOpen&&<div className="overlay"><div className="modal admin-modal"><button className="close" onClick={()=>setStaffOpen(false)}>×</button><p className="eyebrow">JEFE DE OPERACIONES</p><h2>Base de personal operativo</h2><p className="sub">El cargo y estudio base determinan las opciones disponibles. En Exteriores se puede mezclar todo el personal.</p><form className="staff-form" onSubmit={addStaff}><input name="name" placeholder="Nombre completo" required/><select name="role">{CREW_ROLES.map(r=><option key={r}>{r}</option>)}</select><select name="studios"><option value="estudio">Estudio II</option><option value="radio">Estudio I · Radio</option><option value="radio,estudio">Ambos estudios</option></select><button className="primary">Agregar</button></form><div className="staff-list">{staff.map(s=><div key={s.id}><div><b>{s.name}</b><small>{s.role} · {s.studios.includes("radio")?"Estudio I ":""}{s.studios.includes("estudio")?"Estudio II":""}</small></div><button onClick={()=>toggleStaff(s)}>{s.active?"Activo":"Inactivo"}</button></div>)}</div></div></div>}
    {editingStaffOpen&&<div className="overlay"><div className="modal admin-modal"><button className="close" onClick={()=>setEditingStaffOpen(false)}>×</button><p className="eyebrow">EDICIÓN</p><h2>Personal de edición</h2><p className="sub">Editores, camarógrafos, filmmakers y clipeadores disponibles para designar en las grabaciones. Este personal es de otro departamento: no genera horas ni métricas operativas.</p><form className="staff-form" onSubmit={addEditingStaff}><input name="name" placeholder="Nombre completo" required/><select name="role">{EDITING_ROLES.map(r=><option key={r}>{r}</option>)}</select><button className="primary">Agregar</button></form><div className="staff-list">{editingStaff.map(s=><div key={s.id}><div><b>{s.name}</b><small>{s.role}</small></div><button onClick={()=>toggleEditingStaff(s)}>{s.active?"Activo":"Inactivo"}</button></div>)}</div></div></div>}
    {logsOpen&&<div className="overlay"><div className="modal admin-modal"><button className="close" onClick={()=>setLogsOpen(false)}>×</button><p className="eyebrow">CONTROL DE CAMBIOS</p><h2>{["administrador","jefe_produccion"].includes(user?.role||"")?"Bitácora de la agenda":"Mi bitácora de solicitudes"}</h2><p className="sub">{["administrador","jefe_produccion"].includes(user?.role||"")?"Puede revisar las acciones atribuidas a todos los usuarios sobre las solicitudes y la agenda.":"Solo se muestran las acciones realizadas por su cuenta corporativa."}</p><div className="log-list">{logs.length?logs.map(l=><div key={l.id}><b>{l.actorName}</b><span>{l.actorEmail} · Solicitud #{l.reservationId}</span><small>{new Date(l.createdAt+"Z").toLocaleString("es-BO")}</small><p>Acción: {l.action} · Campos: {Object.keys(JSON.parse(l.changes||"{}")).join(", ")||"ninguno"}</p></div>):<div className="empty">No hay cambios registrados para mostrar.</div>}</div></div></div>}
    {metricsOpen&&<div className="overlay"><div className="modal metrics-modal">
      <button className="close" onClick={()=>setMetricsOpen(false)}>×</button><p className="eyebrow">RENDIMIENTO OPERATIVO</p><h2>Métricas mensuales</h2>
      <div className="metric-filter"><input type="month" value={metricMonth} onChange={e=>{setMetricMonth(e.target.value);openMetrics(e.target.value)}}/></div>
      <div className="metric-grid"><Metric label="Solicitudes" value={Number(metrics.total||0)}/><Metric label="Canceladas" value={Number(metrics.cancelled||0)}/><Metric label="Completadas" value={Number(metrics.completed||0)}/><Metric label="Horas solicitadas" value={Number(metrics.requestedHours||0)} hours/><Metric label="Horas efectivas" value={Number(metrics.effectiveHours||0)} hours/><Metric label="Horas reales" value={Number(metrics.actualHours||0)} hours/><Metric label="Horas excedidas" value={Number(metrics.overtimeHours||0)} hours/><Metric label="Horas paradas" value={Number(metrics.lostHours||0)} hours/><Metric label="Horas por retrasos" value={Number(metrics.delayHours||0)} hours/><Metric label="Efectividad" value={Number(metrics.efficiencyPct||0)} suffix="%"/></div>
      <div className="resource-metrics">{Object.entries((metrics.byResource||{}) as unknown as Record<string,{uses:number;hours:number;liveHours?:number;recordingRequestedHours?:number;recordingActualHours?:number;recordingUtilizationPct?:number}>).map(([k,v])=><div key={k}><b>{k}</b><span>{k==="exteriores"?`${formatHours(v.recordingActualHours||0)} reales de ${formatHours(v.recordingRequestedHours||0)} solicitadas · ${(v.recordingUtilizationPct||0).toFixed(1)}%`:`${v.uses} usos · ${formatHours(v.hours)}${v.liveHours?` · ${formatHours(v.liveHours)} en vivo`:""}`}</span></div>)}</div>
      <div className="charts"><BarChart title="Solicitudes por programa" items={((metrics.byProgram||[]) as unknown as {program:string;requests:number}[]).map(p=>({label:p.program,value:p.requests}))}/><BarChart title="Horas excedidas por programa" items={((metrics.byProgram||[]) as unknown as {program:string;overtimeHours:number}[]).map(p=>({label:p.program,value:p.overtimeHours}))}/><BarChart title="Horas reales por operador" items={((metrics.byOperator||[]) as unknown as {name:string;actualHours:number}[]).map(p=>({label:p.name,value:p.actualHours}))}/><BarChart title="Motivos de cancelación" items={(metrics.cancellationReasons||[]) as unknown as {label:string;value:number}[]}/><BarChart title="Motivos de reprogramación" items={(metrics.rescheduleReasons||[]) as unknown as {label:string;value:number}[]}/></div>
      <h3>Uso por programa</h3><div className="program-metrics">{((metrics.byProgram||[]) as unknown as {program:string;logoData:string;requests:number;requestedHours:number;actualHours:number;overtimeHours:number}[]).map(p=><div key={p.program} className="program-metric-row"><span className="metric-program-name">{p.logoData?<img src={p.logoData} alt=""/>:<i/>}<b>{p.program}</b></span><span>{p.requests} solicitudes</span><span>{formatHours(p.requestedHours)} solicitadas</span><span>{formatHours(p.actualHours)} reales</span><span className={p.overtimeHours>0?"overtime-value":""}>{formatHours(p.overtimeHours)} excedidas</span></div>)}</div>
      <h3>Solicitudes por usuario</h3><div className="program-metrics requester-metrics">{((metrics.byRequester||[]) as unknown as {name:string;email:string;area:string;requests:number;cancelled:number;hours:number}[]).map(u=><div key={u.email}><b>{u.name}</b><span>{u.area}</span><span>{u.requests} solicitudes</span><span>{u.cancelled} canceladas</span><span>{u.hours.toFixed(1)} h vigentes</span></div>)}</div>
      <h3>Horas por operador</h3><div className="operator-metrics operator-metrics-simple"><div className="operator-metric-head"><b>Operador</b><b>Funciones</b><b>Turno</b><b>Extraordinario</b><b>Total</b></div>{((metrics.byOperator||[]) as unknown as {name:string;roles:string;shiftHours:number;extraordinaryHours:number}[]).map(o=><div key={o.name}><b>{o.name}</b><span>{o.roles}</span><span>{formatHours(o.shiftHours||0)}</span><span>{formatHours(o.extraordinaryHours||0)}</span><strong>{formatHours((o.shiftHours||0)+(o.extraordinaryHours||0))}</strong></div>)}</div>
      <p className="metric-note">El personal operativo se mide únicamente por las horas definidas en sus turnos. Los turnos extraordinarios se cuentan aparte. Las horas excedidas corresponden al tiempo real utilizado por encima de lo solicitado.</p>
    </div></div>}
    {operationsOpen&&<div className="overlay"><div className="modal operations-modal"><button className="close" onClick={()=>setOperationsOpen(false)}>×</button><p className="eyebrow">JEFE DE OPERACIONES</p><h2>Programas y grilla fija</h2><p className="sub">Este panel queda restringido por el rol asignado a la identidad corporativa.</p><h3>Agregar programa</h3><form className="program-form" onSubmit={addProgram}><input name="name" placeholder="Nombre del programa" required/><input name="color" type="color" defaultValue="#4976BA"/><label>Logo<input name="logo" type="file" accept="image/png,image/jpeg,image/webp"/></label><button className="primary">Agregar</button></form><div className="program-catalog">{programs.map(p=><div key={p.id}>{p.logoData?<img src={p.logoData} alt={`Logo ${p.name}`}/>:<i style={{background:p.color}}/>}<input className="program-name-edit" defaultValue={p.name} onBlur={e=>updateProgram(p,{name:e.target.value.toUpperCase()})}/><input type="color" value={p.color} onChange={e=>updateProgram(p,{color:e.target.value})}/><label className="logo-upload">{p.logoData?"Cambiar logo":"Subir logo"}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>updateProgramLogo(p,e.target.files?.[0])}/></label><button onClick={()=>updateProgram(p,{active:!p.active})}>{p.active?"Activo":"Inactivo"}</button></div>)}</div>{[["Estudio TV","estudio"],["Estudio de Radio","radio"]].map(([label,type])=><section className="schedule-editor" key={type}><h3>Grilla fija · {label}</h3><div className="grid-editor">{blocks.filter(b=>b.resource===type).map(b=><div key={b.id}><input defaultValue={b.startTime} type="time" onBlur={e=>updateBlock(b,{startTime:e.target.value})}/><input defaultValue={b.endTime} type="time" onBlur={e=>updateBlock(b,{endTime:e.target.value})}/><input defaultValue={b.title} onBlur={e=>updateBlock(b,{title:e.target.value})}/><select defaultValue={b.program} onChange={e=>updateBlock(b,{program:e.target.value,color:programs.find(p=>p.name===e.target.value)?.color||b.color})}>{programs.map(p=><option key={p.id}>{p.name}</option>)}</select><button onClick={()=>updateBlock(b,{active:!b.active})}>{b.active?"Activo":"Inactivo"}</button></div>)}</div></section>)}</div></div>}
    {cancelOpen&&<div className="overlay top-overlay"><div className="modal reason-modal"><button className="close" onClick={()=>setCancelOpen(false)}>×</button><p className="eyebrow">CANCELAR GRABACIÓN</p><h2>Motivo de cancelación</h2><p className="sub">El motivo será incluido en la bitácora, métricas y correo. Si se cancela el mismo día desde dos horas antes del inicio, el espacio se registrará como hora parada.</p><label>Motivo<select value={cancelReason} onChange={e=>setCancelReason(e.target.value)}><option value="">Seleccione…</option>{CHANGE_REASONS.map(r=><option key={r}>{r}</option>)}</select></label>{cancelReason==="Otro"&&<label>Especifique<textarea value={cancelDetail} onChange={e=>setCancelDetail(e.target.value)} required/></label>}{error&&<div className="form-error">{error}</div>}<div className="actions"><button onClick={()=>setCancelOpen(false)}>Volver</button><button className="danger" onClick={cancelReservation}>Confirmar cancelación</button></div></div></div>}
    {denialOpen&&<div className="overlay top-overlay"><div className="modal reason-modal"><button className="close" onClick={()=>setDenialOpen(false)}>×</button><p className="eyebrow">RECHAZAR SOLICITUD</p><h2>Indique el motivo</h2><p className="sub">El solicitante recibirá automáticamente un correo corporativo con este motivo. La decisión quedará registrada en la bitácora.</p><label>Motivo del rechazo<textarea value={denialReason} onChange={event=>setDenialReason(event.target.value)} placeholder="Ej.: El estudio estará ocupado por una transmisión especial." autoFocus/></label>{error&&<div className="form-error">{error}</div>}<div className="actions"><button onClick={()=>setDenialOpen(false)}>Volver</button><button className="deny-reservation" onClick={()=>reviewReservation("deny",denialReason)}>Confirmar rechazo y avisar</button></div></div></div>}
    {toast && <div className="toast">✓ {toast}</div>}
  </main>
}

function Schedule({days,reservations,fixed,onEdit}:{days:Date[];reservations:Event[];fixed:Event[];onEdit:(event:Event)=>void}) {
  const hours=Array.from({length:17},(_,i)=>i+6); const now=iso(new Date());
  return <div className="schedule" style={{"--cols":days.length} as React.CSSProperties}><div className="head blank"/>{days.map(d=><div className={`head ${iso(d)===now?"current":""}`} key={iso(d)}><span>{DAYS[(d.getDay()+6)%7]}</span><b>{d.getDate()}</b></div>)}<div className="times">{hours.map(h=><span key={h}>{String(h).padStart(2,"0")}:00</span>)}</div>{days.map(d=>{const dayFixed=fixed.filter(e=>(e.weekdays||"1,2,3,4,5").split(",").includes(String(d.getDay()))),dayReservations=reservations.filter(r=>r.date===iso(d));return <div className="day-column" key={iso(d)}>{hours.map(h=><i key={h} style={{top:`${(h-6)*64}px`}}/>)}{dayFixed.map((e,i)=><EventBlock key={`f${i}`} event={{...e,startTime:e.start,endTime:e.end}} fixed/>)}{dayFixed.filter(e=>normalized(e.kind||"").includes("GRABACION")).map((e,i)=><BufferBlock key={`fb${i}`} end={e.endTime||e.end||""}/>)}{dayReservations.map(r=><EventBlock key={r.id} event={r} onEdit={onEdit}/>)}{dayReservations.filter(r=>!["cancelada","denegada"].includes(r.status||"")&&normalized(r.usageCategory||"GRABACION")==="GRABACION").map(r=><BufferBlock key={`rb${r.id}`} end={r.endTime||""}/>)}</div>})}</div>
}
function EventBlock({event,fixed=false,onEdit}:{event:Event;fixed?:boolean;onEdit?:(event:Event)=>void}) { const [sh,sm]=(event.startTime||"06:00").split(":").map(Number); const [eh,em]=(event.endTime||"07:00").split(":").map(Number); const top=((sh-6)*60+sm)*(64/60); const height=Math.max(28,((eh-sh)*60+em-sm)*(64/60)-4),ghost=event.status==="cancelada",denied=event.status==="denegada",pending=event.status==="pendiente",completed=event.status==="completada",delayed=event.status==="retrasada"; return <div className={`event ${fixed?"fixed":"booking"} ${ghost?"cancelled-ghost":""} ${denied?"denied-event":""} ${pending?"pending-event":""} ${completed?"completed-event":""} ${delayed?"delayed":""}`} onClick={()=>!fixed&&!ghost&&onEdit?.(event)} style={{top,height,background:ghost||denied?"#b9413b":pending?"#c88716":completed?"#238557":event.color,cursor:fixed||ghost?"default":"pointer"}} title={`${event.title} · ${event.startTime}–${event.endTime}${ghost?" · CANCELADA":denied?` · DENEGADA${event.denialReason?` · ${event.denialReason}`:""}`:pending?" · PENDIENTE DE APROBACIÓN":completed?` · FINALIZADA · Uso real ${event.actualStartTime||event.startTime}–${event.actualEndTime||event.endTime}`:delayed?` · RETRASO ${event.delayMinutes} min`:fixed?"":" · Clic para editar"}`}><b>{ghost?"CANCELADA · ":denied?"DENEGADA · ":pending?"PENDIENTE · ":completed?"FINALIZADA · ":delayed?"RETRASADA · ":""}{event.title}</b><span>{event.startTime}–{event.endTime}{completed?` · Real ${event.actualStartTime||event.startTime}–${event.actualEndTime||event.endTime}`:delayed&&event.delayMinutes?` · +${event.delayMinutes} min`:""}</span></div> }
function BufferBlock({end}:{end:string}){if(!end)return null;const top=(timeMinutes(end)-6*60)*(64/60);return <div className="operation-buffer" style={{top,height:16}} title="15 minutos reservados para orden y traslado de Operaciones"><b>OPERACIONES · 15 MIN</b></div>}
function MonthView({cursor,reservations}:{cursor:Date;reservations:Event[]}) { const first=new Date(cursor.getFullYear(),cursor.getMonth(),1); const start=monday(first); return <div className="month"><div className="month-head">{DAYS.map(d=><b key={d}>{d}</b>)}</div><div className="month-grid">{Array.from({length:42},(_,i)=>addDays(start,i)).map(d=><div className={d.getMonth()!==cursor.getMonth()?"muted":""} key={iso(d)}><span>{d.getDate()}</span>{reservations.filter(r=>r.date===iso(d)).slice(0,3).map(r=>{const cancelled=r.status==="cancelada",denied=r.status==="denegada",pending=r.status==="pendiente",completed=r.status==="completada";return <i key={r.id} className={cancelled?"month-cancelled":completed?"month-completed":""} style={{background:cancelled||denied?"#b9413b":pending?"#c88716":completed?"#238557":r.color}}>{r.startTime} {cancelled?"CANCELADA · ":denied?"DENEGADA · ":pending?"PENDIENTE · ":completed?"FINALIZADA · ":""}{r.title}</i>})}</div>)}</div></div> }
function Availability({reservations}:{reservations:Event[];fixed:Event[]}) { const today=iso(new Date()),count=(type:string)=>reservations.filter(r=>r.date===today&&r.locationType===type&&!["cancelada","denegada"].includes(r.status||"")).length; return <>{[["Estudio TV","estudio"],["Estudio de Radio","radio"],["Exteriores","exteriores"]].map(([label,type])=><div className="availability" key={type}><div><b>{label}</b><span>Solicitudes vigentes hoy</span></div><strong>{count(type)}</strong></div>)}</> }
function Metric({label,value,hours=false,suffix=""}:{label:string;value:number;hours?:boolean;suffix?:string}){return <div><span>{label}</span><b>{hours?formatHours(value):`${value.toFixed(suffix?1:0)}${suffix}`}</b></div>}
function formatHours(value:number){const total=Math.round(value*60),hours=Math.floor(total/60),minutes=total%60;return minutes?`${hours} h ${minutes} min`:`${hours} h`}
function BarChart({title,items}:{title:string;items:{label:string;value:number}[]}){const shown=items.filter(i=>i.value>0).sort((a,b)=>b.value-a.value).slice(0,8),max=Math.max(1,...shown.map(i=>i.value));return <div className="bar-chart"><h4>{title}</h4>{shown.length?shown.map(i=><div key={i.label}><span>{i.label}</span><i><b style={{width:`${(i.value/max)*100}%`}}/></i><strong>{i.value}</strong></div>):<p>Sin datos este mes</p>}</div>}














